def solve(rows):
    import pandas as pd
    if not rows:
        return []
    lines = pd.DataFrame(rows)
    return (lines.groupby("customer_id", as_index=False)
            .agg(total_amount=("amount", "sum"),
                 line_count=("amount", "size"))
            .sort_values("customer_id").to_dict("records"))

